import{z as l,x as A,o as t,c as p,q as r,j as i,D as e,d as s,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"极大似然与贝叶斯","description":"","frontmatter":{"title":"极大似然与贝叶斯","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mle-bayesian-econ.md","filePath":"econ/mle-bayesian-econ.md","lastUpdated":1791413859000}'),d={name:"econ/mle-bayesian-econ.md"};function C(m,a,M,h,D,c){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="极大似然与贝叶斯" tabindex="-1">极大似然与贝叶斯 <a class="header-anchor" href="#极大似然与贝叶斯" aria-label="Permalink to &quot;极大似然与贝叶斯&quot;">​</a></h1><div class="epigraph"><p>似然把模型写成观测的密度；极大似然找使密度最大的参数，贝叶斯把参数当随机、用先验更新。两者都比 GMM 更吃分布假设，也都能把上一课的预报密度变成决策。</p><footer>—— Fisher 似然传统；Wald 与 Cramér–Rao；Sims 宏观贝叶斯；Geweke 后验模拟</footer></div><p><a href="/econ/forecast-evaluation-dm">上一课</a>用损失比较预报。本课收束「结构与预测」：极大似然（MLE）与贝叶斯作为估计原则，而不是又一种识别设计。下一课<a href="/econ/fe-re">固定效应</a>才把时不变异质吸进组内；计量课程尚未结束。后课默认已经读完：设计给支撑内因果，结构给反事实，似然 / 贝叶斯给在模型内的估计与密度预报。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GMM 用有限矩，分布可以错很多仍一致（矩对的话）。MLE 要整条密度 \\(f(Y\\mid\\theta)\\)。对了：有效（达到信息界）、不变性、嵌套检验（LR / Wald / LM 三位一体）。错了：准极大似然在某些族（正态、泊松）对均值参数仍一致，否则可以既偏且「很显著」。缺口是：离散选择、DSGE、状态空间，似然自然；因果设计课的 LATE 不必有密度。贝叶斯：先验 \\(\\pi(\\theta)\\)，后验 \\(\\propto L(\\theta)\\pi(\\theta)\\)。有限样本陈述是概率的，不是「\\(N\\to\\infty\\) 覆盖」。先验在宏观小样本里不是装饰——Sims 强调这一点。</p><p><span class="marginnote">识别：似然平坦则 MLE 乱跳、后验跟着先验走。上一单元 BLP、拍卖的识别问题不会因为改用 MCMC 消失。贝叶斯把识别弱写成先验敏感，这是优点若你报告，是缺点若你藏。</span></p><p><span class="marginnote">数字实例（共轭更新）：抛硬币用 Beta 先验——先验 \\(\\mathrm{Beta}(1,1)\\)（一无所知）加 7 正 3 反的数据，后验就是 \\(\\mathrm{Beta}(8,4)\\)，均值 \\(8/12\\approx 0.67\\)；若先验换成 \\(\\mathrm{Beta}(50,50)\\)（强烈相信硬币公平），后验为 \\(\\mathrm{Beta}(57,53)\\)，均值 \\(\\approx 0.52\\)，被强先验拽向 1/2。先验越硬，同样的数据挪动后验越少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MLE：写出 \\(L\\)，数值最大化，信息矩阵给标准误；QMLE 用三明治（又接到<a href="/econ/inference-robust-cluster">稳健推断</a>）。LR 检验嵌套约束。贝叶斯：共轭时手算；否则 MCMC（Metropolis–Hastings、Gibbs）、SMC。报告先验、后验区间、边际似然（模型比较）。预报：后验预测分布直接给密度预报，log score 与上一课衔接。</p>',9)),(t(),i(B,null,{default:e(()=>[o(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DENS%5B%22%E5%AF%86%E5%BA%A6%20f(Y%7C%CE%B8)%22%5D%20--%3E%20MLE%5B%22%E6%9E%81%E5%A4%A7%E4%BC%BC%E7%84%B6%22%5D%0A%20%20DENS%20--%3E%20BAY%5B%22%E5%85%88%E9%AA%8C%20%E2%86%92%20%E5%90%8E%E9%AA%8C%22%5D%0A%20%20MLE%20--%3E%20EFF%5B%22%E5%88%86%E5%B8%83%E5%AF%B9%E5%88%99%E6%9C%89%E6%95%88%22%5D%0A%20%20MISS%5B%22%E5%AF%86%E5%BA%A6%E9%94%99%22%5D%20--%3E%20QML%5B%22%E6%9C%89%E6%97%B6%E4%BB%8D%E4%B8%80%E8%87%B4%2C%20%E6%9C%89%E6%97%B6%E5%BE%88%E5%81%8F%22%5D%0A%20%20FLAT%5B%22%E4%BC%BC%E7%84%B6%E5%B9%B3%E5%9D%A6%22%5D%20--%3E%20PRI%5B%22%E5%90%8E%E9%AA%8C%E8%A2%AB%E5%85%88%E9%AA%8C%E6%94%AF%E9%85%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 GMM：矩是似然得分的子集。过度识别 \\(J\\) 对应先验之外的检验。宏观 DSGE 常用贝叶斯，因为似然难、先验把弱识别按住——必须把先验当研究设计的一部分公开。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"「MCMC」翻译成大白话：不直接算后验公式，而是让参数值在空间里随机溜达，密度高的地方多停、密度低的地方少停——停留频率渐近就是后验。它不是在「找最优点」（那是 MLE 的事），而是在「采样整个分布」，所以诊断要看链是否走遍、收敛到同一处。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"机制是概率模型。MLE 把样本当成密度的重复；依赖（时间序列）要写成条件似然，不能假装 i.i.d.。贝叶斯把未知 \\(\\theta\\) 送进联合分布，学习规则是 Bayes 定理。渐近上，正则情况下后验收缩到 MLE 附近（Bernstein–von Mises），于是大样本两者说话接近；识别弱或先验强时不接近。",-1)),(t(),i(B,null,{default:e(()=>[o(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PRI%5B%22%E5%85%88%E9%AA%8C%20%CF%80(%CE%B8)%EF%BC%9A%E6%95%B0%E6%8D%AE%E4%B9%8B%E5%A4%96%E7%9A%84%E4%BF%A1%E5%BF%B5%22%5D%20--%3E%20POST%5B%22%E5%90%8E%E9%AA%8C%20%E2%88%9D%20L(%CE%B8)%20%C3%97%20%CF%80(%CE%B8)%22%5D%0A%20%20LIK%5B%22%E4%BC%BC%E7%84%B6%20L(%CE%B8)%EF%BC%9A%E6%95%B0%E6%8D%AE%E8%AF%B4%E4%BA%86%E4%BB%80%E4%B9%88%22%5D%20--%3E%20POST%0A%20%20POST%20--%3E%20PRED%5B%22%E5%90%8E%E9%AA%8C%E9%A2%84%E6%B5%8B%E5%88%86%E5%B8%83%20%E2%86%92%20%E5%AF%86%E5%BA%A6%E9%A2%84%E6%8A%A5%22%5D%0A%20%20POST%20--%3E%20SHR%5B%22n%20%E5%A2%9E%E5%A4%A7%EF%BC%9A%E5%90%8E%E9%AA%8C%E6%94%B6%E7%BC%A9%E5%88%B0%20MLE%20%E9%99%84%E8%BF%91%EF%BC%88BvM%EF%BC%89%22%5D%0A%20%20FLAT%5B%22%E4%BC%BC%E7%84%B6%E5%B9%B3%E5%9D%A6%20%2F%20%E5%BC%B1%E8%AF%86%E5%88%AB%22%5D%20--%3E%20DOM%5B%22%E5%85%88%E9%AA%8C%E6%94%AF%E9%85%8D%E5%90%8E%E9%AA%8C%EF%BC%9A%E4%B8%A4%E8%80%85%E5%88%86%E9%81%93%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">「Bernstein–von Mises」的直觉：数据越多，先验的嗓门越小——像辩论场上证据逐渐占满全场，开局立场的影响被稀释。小样本（宏观常见）时先验才有话语权，这正是 Sims 强调「先验不是装饰」的原因：同一模型、不同先验，政策答案可以不同。</span></p><p>与卢卡斯：似然若是简化式 VAR，政策分析仍犯批判。结构似然（均衡已经解过）才把规则放进 \\(f\\)。贝叶斯 DSGE 不是自动结构正确，只是结构加上先验。</p><p><span class="marginnote">Lancaster、Rossi 的微观贝叶斯：分层模型把异质 \\(\\beta_i\\) 写成分布，这是随机系数，与因果森林的 \\(\\tau(x)\\) 目标不同，但都承认异质。声明目标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教软件平台。不把 MCMC 诊断写成课的主体。计量课程到此尚未结束：下一课固定效应回到面板；等面板与推断收束，下一门课才换成宏观核算的账，不再是 \\(\\theta\\) 如何估。不要用本课去重写大模型的训练损失，那是另一栏的下一 token。</p><p>后课默认：写出密度就要接受错分布的代价；贝叶斯必须报告先验敏感。识别不来自计算。预报密度用后验预测 + 上一课的 log score。因果 LATE 仍用设计，不必强迫似然。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLE：密度对则有效；错则可能偏。QMLE 三明治管部分错误。</li><li>贝叶斯：后验 = 似然 × 先验；弱识别时先验支配。</li><li>大样本正则时两者靠近；小样本与平坦似然时分道。</li><li>结构似然才服务政策；VAR 似然仍是约化形式。</li><li>出处：Fisher；Wald；Sims 贝叶斯宏观；Geweke；Bernstein–von Mises 传统。</li></ul>',8))])}const u=l(d,[["render",C]]);export{L as __pageData,u as default};
